# ── Constants ──────────────────────────────────────────────────────────────────
# DuckDB EXTRACT(DOW): 0=Sunday, 1=Monday … 6=Saturday
DOW_MAP   = {0: "Sun", 1: "Mon", 2: "Tue", 3: "Wed", 4: "Thu", 5: "Fri", 6: "Sat"}
DOW_ORDER = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

WEEK_COLORS = {
    "Week 1": "#4b9eff",
    "Week 2": "#00c4ff",
    "Week 3": "#a78bfa",
    "Week 4": "#34d399",
    "Week 5": "#fb923c",
}

# Confirmed DQ issue dates — used to annotate revenue chart
DQ_EVENTS = {
    "2025-03-15": {"label": "DUPE",   "color": "#ff4b4b", "short": "Duplication"},
    "2025-03-22": {"label": "SCHEMA", "color": "#4b9eff", "short": "Schema Drift"},
    "2025-03-26": {"label": "NULL",   "color": "#ffa500", "short": "Null Spike"},
    "2025-03-18": {"label": "LATE",   "color": "#a78bfa", "short": "Late File"},
}

# Pipeline check descriptions (matches quality_checks.py check names)
CHECK_DESC = {
    "row_counts":        "Validates each source file contains 5,000–10,000 rows. "
                         "Files outside range or missing dates are flagged.",
    "schema":            "Verifies all 10 expected columns exist in raw_orders after "
                         "ingest-time normalization (e.g. item_name → product_name).",
    "duplicates":        "Detects order_ids appearing in more than one source file. "
                         "Identifies re-deliveries such as March 15 re-sending March 14 data.",
    "date_completeness": "Checks every calendar date in March 2025 has at least one file "
                         "loaded. Flags missing delivery dates (e.g. March 31).",
    "null_rates":        "Measures per-file null % on critical columns: order_id, customer_id, "
                         "qty, unit_price, discount_pct. Any file exceeding 5% is flagged.",
}

CHART_LAYOUT = dict(
    template="plotly_dark",
    paper_bgcolor="#0d1b2a",
    plot_bgcolor="#0d1b2a",
    font=dict(family="Inter, system-ui, sans-serif", color="#c0cfe0"),
    title_font=dict(color="#ffffff", size=15),
    margin=dict(t=50, b=40, l=10, r=10),
)

GRID = dict(gridcolor="#1e3a4a", zerolinecolor="#1e3a4a")

# ── DB path resolution ─────────────────────────────────────────────────────────
_here = os.path.dirname(os.path.abspath(__file__))
_candidates = [
    os.path.join(_here, "output", "sales.duckdb"),
    os.path.join(_here, "..", "output", "sales.duckdb"),
    os.path.join(os.getcwd(), "output", "sales.duckdb"),
]
DB_PATH = next((p for p in _candidates if os.path.exists(p)), _candidates[1])


@st.cache_resource
def get_connection():
    if not os.path.exists(DB_PATH):
        return None
    return duckdb.connect(DB_PATH, read_only=True)


@st.cache_data(ttl=300)
def query(_con, sql: str) -> pd.DataFrame:
    return _con.execute(sql).df()


# ── Page header ────────────────────────────────────────────────────────────────
st.markdown("""
<div class="dash-title">
  <div class="eyebrow">Sales Intelligence Platform</div>
  <h1>March 2025 — Executive Revenue Summary</h1>
  <p class="subtitle">
    30 daily CSV files &nbsp;·&nbsp; DuckDB warehouse &nbsp;·&nbsp;
    4 data-quality issues detected &amp; resolved &nbsp;·&nbsp;
    Pipeline: ingest → validate → transform → model
  </p>
</div>
""", unsafe_allow_html=True)

con = get_connection()
if con is None:
    st.error(f"Database not found at `{DB_PATH}`. Run `python pipeline/run_pipeline.py` first.")
    st.stop()

# ── Tabs ───────────────────────────────────────────────────────────────────────
tab1, tab2, tab3 = st.tabs([
    "  Revenue Performance  ",
    "  Product Intelligence  ",
    "  Data Quality Audit  ",
])


# ══════════════════════════════════════════════════════════════════════════════
# TAB 1 — REVENUE PERFORMANCE
# ══════════════════════════════════════════════════════════════════════════════
with tab1:

    # ── KPI Cards ──────────────────────────────────────────────────────────────
    kpis = query(con, """
        SELECT
            ROUND(SUM(revenue), 2)         AS total_revenue,
            COUNT(*)                        AS total_orders,
            ROUND(AVG(revenue), 2)          AS avg_order_value,
            COUNT(DISTINCT customer_id)     AS unique_customers
        FROM fact_orders
    """).iloc[0]

    st.markdown(f"""
    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="label">Total Revenue</div>
        <div class="value">Rs. {kpis['total_revenue']:,.0f}</div>
        <div class="sub">March 2025 · clean orders only</div>
      </div>
      <div class="kpi-card">
        <div class="label">Orders Processed</div>
        <div class="value">{int(kpis['total_orders']):,}</div>
        <div class="sub">after deduplication</div>
      </div>
      <div class="kpi-card">
        <div class="label">Avg Order Value</div>
        <div class="value">Rs. {kpis['avg_order_value']:,.2f}</div>
        <div class="sub">per transaction</div>
      </div>
      <div class="kpi-card">
        <div class="label">Unique Customers</div>
        <div class="value">{int(kpis['unique_customers']):,}</div>
        <div class="sub">distinct customer IDs</div>
      </div>
    </div>
    """, unsafe_allow_html=True)

    st.markdown("<div style='height:12px'></div>", unsafe_allow_html=True)

    # ── Daily Revenue — annotated line chart ───────────────────────────────────
    st.markdown('<div class="section-label">Daily Revenue Trend</div>', unsafe_allow_html=True)

    daily = query(con, """
        SELECT order_date, total_revenue, order_count, is_weekend, day_of_week
        FROM daily_revenue
        ORDER BY order_date
    """)
    daily["order_date"] = pd.to_datetime(daily["order_date"])

    fig_daily = go.Figure()

    # Weekend shading
    for _, row in daily[daily["is_weekend"] == True].iterrows():
        fig_daily.add_vrect(
            x0=row["order_date"], x1=row["order_date"] + pd.Timedelta(days=1),
            fillcolor="#1e3a4a", opacity=0.45, line_width=0,
        )

    # DQ issue vertical lines
    for date_str, meta in DQ_EVENTS.items():
        fig_daily.add_vline(
            x=date_str, line_dash="dot", line_color=meta["color"], line_width=1.5,
        )
        fig_daily.add_annotation(
            x=date_str,
            y=daily["total_revenue"].max() * 1.04,
            text=f"<b>{meta['label']}</b>",
            showarrow=False,
            font=dict(color=meta["color"], size=9, family="Inter, sans-serif"),
            bgcolor="#0d1b2a",
            bordercolor=meta["color"],
            borderpad=3,
        )

    # Revenue line
    fig_daily.add_trace(go.Scatter(
        x=daily["order_date"],
        y=daily["total_revenue"],
        mode="lines+markers",
        line=dict(color="#00c4ff", width=2.5),
        marker=dict(size=5, color="#00c4ff"),
        customdata=daily[["order_count"]],
        hovertemplate=(
            "<b>%{x|%d %b %Y}</b><br>"
            "Revenue: Rs. %{y:,.0f}<br>"
            "Orders: %{customdata[0]:,}<extra></extra>"
        ),
        name="Daily Revenue",
    ))

    fig_daily.update_layout(
        **CHART_LAYOUT,
        height=320,
        showlegend=False,
        xaxis=dict(title="", **GRID, tickformat="%d %b"),
        yaxis=dict(title="Revenue (Rs.)", **GRID, tickformat=",.0f"),
        hovermode="x unified",
    )
    fig_daily.update_layout(
        annotations=fig_daily.layout.annotations + (
            go.layout.Annotation(
                x=0.01, y=-0.18, xref="paper", yref="paper",
                text="Shaded bands = weekends  ·  Dotted lines = DQ issue dates",
                showarrow=False, font=dict(size=10, color="#4a7a9b"),
            ),
        )
    )
    st.plotly_chart(fig_daily, use_container_width=True)

    # ── Week-over-Week Revenue by Day of Week ──────────────────────────────────
    st.markdown('<div class="section-label">Week-over-Week Pattern — Revenue by Day of Week</div>',
                unsafe_allow_html=True)

    wow_raw = query(con, """
        SELECT
            order_date,
            total_revenue,
            order_count,
            day_of_week,
            CASE
                WHEN EXTRACT(DAY FROM order_date) BETWEEN 1  AND 2  THEN 1
                WHEN EXTRACT(DAY FROM order_date) BETWEEN 3  AND 9  THEN 2
                WHEN EXTRACT(DAY FROM order_date) BETWEEN 10 AND 16 THEN 3
                WHEN EXTRACT(DAY FROM order_date) BETWEEN 17 AND 23 THEN 4
                WHEN EXTRACT(DAY FROM order_date) BETWEEN 24 AND 30 THEN 5
            END AS march_week
        FROM daily_revenue
        ORDER BY order_date
    """)
    wow_raw["order_date"] = pd.to_datetime(wow_raw["order_date"])
    wow_raw["dow_label"]  = wow_raw["day_of_week"].map(DOW_MAP)
    wow_raw["week_label"] = "Week " + wow_raw["march_week"].astype(int).astype(str)
    wow_raw["date_str"]   = wow_raw["order_date"].dt.strftime("%d %b")

    # sort within each week by canonical DOW order
    dow_sort = {d: i for i, d in enumerate(DOW_ORDER)}
    wow_raw["_dow_sort"] = wow_raw["dow_label"].map(dow_sort)
    wow_raw = wow_raw.sort_values(["march_week", "_dow_sort"])

    fig_wow = go.Figure()
    for week_label, grp in wow_raw.groupby("week_label", sort=True):
        grp = grp.sort_values("_dow_sort")
        fig_wow.add_trace(go.Scatter(
            x=grp["dow_label"],
            y=grp["total_revenue"],
            mode="lines+markers",
            name=week_label,
            line=dict(color=WEEK_COLORS.get(week_label, "#ffffff"), width=2.5),
            marker=dict(size=9, symbol="circle",
                        line=dict(color="#0d1b2a", width=1.5)),
            customdata=grp[["date_str", "order_count"]],
            hovertemplate=(
                f"<b>{{%x}}</b> ({week_label})<br>"
                "Date: %{customdata[0]}<br>"
                "Revenue: Rs. %{y:,.0f}<br>"
                "Orders: %{customdata[1]:,}<extra></extra>"
            ),
        ))

    fig_wow.update_layout(
        **CHART_LAYOUT,
        height=380,
        xaxis=dict(
            title="Day of Week",
            categoryorder="array",
            categoryarray=DOW_ORDER,
            **GRID,
        ),
        yaxis=dict(title="Revenue (Rs.)", tickformat=",.0f", **GRID),
        legend=dict(
            bgcolor="#1a2b3c", bordercolor="#1e3a4a", borderwidth=1,
            font=dict(size=11), title=dict(text="Week of March", font=dict(color="#8fa3b1")),
        ),
        hovermode="x unified",
    )
    st.plotly_chart(fig_wow, use_container_width=True)
    st.caption(
        "Week 1 = Mar 1–2 (Sat–Sun only) · Week 2 = Mar 3–9 · Week 3 = Mar 10–16 · "
        "Week 4 = Mar 17–23 · Week 5 = Mar 24–30  |  Mar 31 missing (no file delivered)"
    )


# ══════════════════════════════════════════════════════════════════════════════
# TAB 2 — PRODUCT INTELLIGENCE
# ══════════════════════════════════════════════════════════════════════════════
with tab2:

    # ── Product + Category charts side-by-side ─────────────────────────────────
    st.markdown('<div class="section-label">Revenue Breakdown</div>', unsafe_allow_html=True)

    prod_rev = query(con, """
        SELECT
            p.product_name,
            p.category,
            ROUND(SUM(f.revenue), 2) AS revenue,
            COUNT(*)                  AS orders,
            ROUND(AVG(f.revenue), 2)  AS avg_rev
        FROM fact_orders f
        JOIN dim_products p USING (product_id)
        GROUP BY p.product_name, p.category
        ORDER BY revenue DESC
    """)

    cat_rev = query(con, """
        SELECT category, ROUND(SUM(revenue), 2) AS revenue
        FROM fact_orders
        GROUP BY category
        ORDER BY revenue DESC
    """)

    # Consistent category colors
    CAT_COLORS = {
        "Electronics":    "#00c4ff",
        "Apparel":        "#a78bfa",
        "Grocery":        "#34d399",
        "Stationery":     "#fb923c",
        "Home & Kitchen": "#f472b6",
    }
    prod_rev["color"] = prod_rev["category"].map(CAT_COLORS).fillna("#8fa3b1")

    col_left, col_right = st.columns([3, 2])

    with col_left:
        fig_prod = go.Figure(go.Bar(
            x=prod_rev["revenue"],
            y=prod_rev["product_name"],
            orientation="h",
            marker=dict(color=prod_rev["color"], opacity=0.9),
            customdata=prod_rev[["category", "orders", "avg_rev"]],
            hovertemplate=(
                "<b>%{y}</b><br>"
                "Category: %{customdata[0]}<br>"
                "Revenue: Rs. %{x:,.0f}<br>"
                "Orders: %{customdata[1]:,}<br>"
                "Avg: Rs. %{customdata[2]:,.2f}<extra></extra>"
            ),
        ))
        fig_prod.update_layout(
            **CHART_LAYOUT,
            title="Revenue by Product",
            height=420,
            showlegend=False,
            xaxis=dict(title="Revenue (Rs.)", tickformat=",.0f", **GRID),
            yaxis=dict(categoryorder="total ascending", **GRID),
        )
        st.plotly_chart(fig_prod, use_container_width=True)

    with col_right:
        fig_cat = go.Figure(go.Pie(
            labels=cat_rev["category"],
            values=cat_rev["revenue"],
            hole=0.52,
            marker=dict(colors=[CAT_COLORS.get(c, "#8fa3b1") for c in cat_rev["category"]],
                        line=dict(color="#0d1b2a", width=2)),
            textposition="inside",
            textinfo="percent+label",
            textfont=dict(size=11, color="#ffffff"),
            hovertemplate="<b>%{label}</b><br>Revenue: Rs. %{value:,.0f}<br>Share: %{percent}<extra></extra>",
        ))
        fig_cat.update_layout(
            **CHART_LAYOUT,
            title="Revenue by Category",
            height=420,
            showlegend=False,
        )
        fig_cat.add_annotation(
            text="By<br>Category", x=0.5, y=0.5, showarrow=False,
            font=dict(size=13, color="#8fa3b1"),
        )
        st.plotly_chart(fig_cat, use_container_width=True)

    st.markdown("<div style='height:4px'></div>", unsafe_allow_html=True)

    # ── Revenue by Region — multi-line over time ───────────────────────────────
    st.markdown('<div class="section-label">Regional Revenue Trend</div>', unsafe_allow_html=True)

    region_daily = query(con, """
        SELECT
            order_date,
            region,
            ROUND(SUM(revenue), 2) AS revenue,
            COUNT(*) AS orders
        FROM fact_orders
        GROUP BY order_date, region
        ORDER BY order_date, region
    """)
    region_daily["order_date"] = pd.to_datetime(region_daily["order_date"])

    REGION_COLORS = {"North": "#00c4ff", "South": "#34d399", "East": "#fb923c", "West": "#a78bfa"}

    fig_reg = go.Figure()
    for region, grp in region_daily.groupby("region"):
        grp = grp.sort_values("order_date")
        fig_reg.add_trace(go.Scatter(
            x=grp["order_date"],
            y=grp["revenue"],
            mode="lines+markers",
            name=region,
            line=dict(color=REGION_COLORS.get(region, "#8fa3b1"), width=2),
            marker=dict(size=4),
            customdata=grp[["orders"]],
            hovertemplate=(
                f"<b>{region}</b>  %{{x|%d %b}}<br>"
                "Revenue: Rs. %{y:,.0f}<br>"
                "Orders: %{customdata[0]:,}<extra></extra>"
            ),
        ))

    fig_reg.update_layout(
        **CHART_LAYOUT,
        title="Daily Revenue by Region",
        height=320,
        xaxis=dict(title="", tickformat="%d %b", **GRID),
        yaxis=dict(title="Revenue (Rs.)", tickformat=",.0f", **GRID),
        legend=dict(bgcolor="#1a2b3c", bordercolor="#1e3a4a", borderwidth=1),
        hovermode="x unified",
    )
    st.plotly_chart(fig_reg, use_container_width=True)

    # ── Top 10 Customers ───────────────────────────────────────────────────────
    st.markdown('<div class="section-label">Top 10 Customers by Total Spend</div>',
                unsafe_allow_html=True)

    top_cust = query(con, """
        SELECT
            customer_id                     AS "Customer ID",
            COUNT(*)                        AS "Orders",
            ROUND(SUM(revenue), 2)          AS "Total Spend (Rs.)",
            ROUND(AVG(revenue), 2)          AS "Avg Order (Rs.)",
            COUNT(DISTINCT product_id)      AS "Distinct Products"
        FROM fact_orders
        GROUP BY customer_id
        ORDER BY "Total Spend (Rs.)" DESC
        LIMIT 10
    """)
    top_cust.index = range(1, 11)
    st.dataframe(top_cust, use_container_width=True)


