# TAB 3 — DATA QUALITY AUDIT
# ══════════════════════════════════════════════════════════════════════════════
with tab3:

    # ── 4 Confirmed Issues ─────────────────────────────────────────────────────
    st.markdown('<div class="section-label">Confirmed Data Quality Issues — 4 Found, 4 Resolved</div>',
                unsafe_allow_html=True)

    col_a, col_b = st.columns(2)

    with col_a:
        st.markdown("""
        <div class="issue-card issue-critical">
          <span class="badge badge-critical">CRITICAL</span>
          <div class="issue-title">Data Duplication</div>
          <div class="issue-date">sales_2025-03-15.csv</div>
          <div class="issue-desc">
            File is a complete re-delivery of March 14 data. All order timestamps
            show <strong>2025-03-14</strong> instead of March 15, causing every
            order_id to duplicate the prior day.
          </div>
          <div class="issue-fix">
            <strong>Impact:</strong> Would have double-counted ~6,100 rows of revenue.<br>
            <strong>Fix:</strong> Deduplicated on order_id (last-write-wins). Excess rows removed.
          </div>
          <span class="resolved">&#10003; Resolved</span>
        </div>
        """, unsafe_allow_html=True)

        st.markdown("""
        <div class="issue-card issue-high">
          <span class="badge badge-high">HIGH</span>
          <div class="issue-title">Null Value Spike</div>
          <div class="issue-date">sales_2025-03-26.csv</div>
          <div class="issue-desc">
            Abnormally high null rates in critical revenue columns:
            <strong>unit_price</strong> (&gt;35% null) and
            <strong>product_name</strong> (&gt;20% null).
            Revenue cannot be calculated for these rows.
          </div>
          <div class="issue-fix">
            <strong>Impact:</strong> Thousands of rows would produce NULL revenue.<br>
            <strong>Fix:</strong> Rows quarantined before fact table load. Excluded from all metrics.
          </div>
          <span class="resolved">&#10003; Resolved</span>
        </div>
        """, unsafe_allow_html=True)

    with col_b:
        st.markdown("""
        <div class="issue-card issue-high">
          <span class="badge badge-high">HIGH</span>
          <div class="issue-title">Schema Drift</div>
          <div class="issue-date">sales_2025-03-22.csv</div>
          <div class="issue-desc">
            Column <strong>product_name</strong> was renamed to <strong>item_name</strong>
            by the upstream system, and an extra column <strong>channel</strong> was appended.
            A naive load would make product_name NULL for the entire day.
          </div>
          <div class="issue-fix">
            <strong>Impact:</strong> Full day of product data silently lost without normalization.<br>
            <strong>Fix:</strong> Ingest layer renames item_name → product_name; drops channel.
          </div>
          <span class="resolved">&#10003; Resolved</span>
        </div>
        """, unsafe_allow_html=True)

        st.markdown("""
        <div class="issue-card issue-medium">
          <span class="badge badge-medium">MEDIUM</span>
          <div class="issue-title">Late File Delivery</div>
          <div class="issue-date">sales_2025-03-18.csv</div>
          <div class="issue-desc">
            File arrived in the <strong>late_arrivals/</strong> subdirectory rather
            than the main datasets folder. A naive glob on the main directory only
            would silently skip the entire day.
          </div>
          <div class="issue-fix">
            <strong>Impact:</strong> Full day of revenue (~March 18) would be missing from reports.<br>
            <strong>Fix:</strong> Pipeline scans both datasets/ and datasets/late_arrivals/ on every run.
          </div>
          <span class="resolved">&#10003; Resolved</span>
        </div>
        """, unsafe_allow_html=True)

    st.markdown("<div style='height:8px'></div>", unsafe_allow_html=True)

    # ── Pipeline Check Results ─────────────────────────────────────────────────
    st.markdown('<div class="section-label">Pipeline Check Results</div>', unsafe_allow_html=True)

    dq = query(con, """
        SELECT check_name, status, details, rows_affected, run_timestamp
        FROM dq_results
        ORDER BY check_name
    """)

    # Build enriched display table
    dq_display = dq.copy()
    dq_display["What It Checks"] = dq_display["check_name"].map(CHECK_DESC).fillna("—")

    STATUS_HTML = {
        "PASS": '<span class="pill-pass">PASS</span>',
        "WARN": '<span class="pill-warn">WARN</span>',
        "FAIL": '<span class="pill-fail">FAIL</span>',
    }

    # Show as styled HTML table
    rows_html = ""
    for _, r in dq_display.iterrows():
        pill = STATUS_HTML.get(r["status"], r["status"])
        rows_html += f"""
        <tr>
          <td style="color:#ffffff;font-weight:600;white-space:nowrap">{r['check_name']}</td>
          <td style="color:#8fa3b1;font-size:11px;max-width:260px">{r['What It Checks']}</td>
          <td>{pill}</td>
          <td style="color:#fb923c;text-align:right;font-weight:600">{int(r['rows_affected']):,}</td>
          <td style="color:#6b8fa6;font-size:11px">{r['details'][:120]}{'…' if len(r['details']) > 120 else ''}</td>
          <td style="color:#4a7a9b;font-size:10px;white-space:nowrap">{str(r['run_timestamp'])[:16]}</td>
        </tr>"""

    st.markdown(f"""
    <div style="overflow-x:auto">
    <table style="width:100%;border-collapse:collapse;font-family:Inter,sans-serif;font-size:12px">
      <thead>
        <tr style="border-bottom:1px solid #1e3a4a">
          <th style="text-align:left;padding:8px 12px;color:#8fa3b1;font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:0.08em">Check</th>
          <th style="text-align:left;padding:8px 12px;color:#8fa3b1;font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:0.08em">What It Validates</th>
          <th style="text-align:left;padding:8px 12px;color:#8fa3b1;font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:0.08em">Status</th>
          <th style="text-align:right;padding:8px 12px;color:#8fa3b1;font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:0.08em">Rows</th>
          <th style="text-align:left;padding:8px 12px;color:#8fa3b1;font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:0.08em">Details</th>
          <th style="text-align:left;padding:8px 12px;color:#8fa3b1;font-weight:600;text-transform:uppercase;font-size:10px;letter-spacing:0.08em">Run At</th>
        </tr>
      </thead>
      <tbody>
        {rows_html}
      </tbody>
    </table>
    </div>
    """, unsafe_allow_html=True)

    st.markdown("<div style='height:16px'></div>", unsafe_allow_html=True)

    # ── Null Rate Heatmap ──────────────────────────────────────────────────────
    st.markdown('<div class="section-label">Null Rate Heatmap — Column × File Date</div>',
                unsafe_allow_html=True)

    null_wide = query(con, """
        SELECT
            CAST(_file_date AS VARCHAR)                                                   AS file_date,
            ROUND(100.0 * SUM(CASE WHEN order_id      IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS order_id,
            ROUND(100.0 * SUM(CASE WHEN customer_id   IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS customer_id,
            ROUND(100.0 * SUM(CASE WHEN product_id    IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS product_id,
            ROUND(100.0 * SUM(CASE WHEN product_name  IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS product_name,
            ROUND(100.0 * SUM(CASE WHEN category      IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS category,
            ROUND(100.0 * SUM(CASE WHEN qty           IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS qty,
            ROUND(100.0 * SUM(CASE WHEN unit_price    IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS unit_price,
            ROUND(100.0 * SUM(CASE WHEN discount_pct  IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS discount_pct,
            ROUND(100.0 * SUM(CASE WHEN region        IS NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS region
        FROM raw_orders
        GROUP BY _file_date
        ORDER BY _file_date
    """)

    heat_cols = ["order_id", "customer_id", "product_id", "product_name",
                 "category", "qty", "unit_price", "discount_pct", "region"]
    null_long  = null_wide.melt(id_vars="file_date", value_vars=heat_cols,
                                var_name="column", value_name="null_pct")
    heat_matrix = null_long.pivot(index="column", columns="file_date", values="null_pct")
    # Shorten date labels: "2025-03-01" → "03-01"
    heat_matrix.columns = [c[5:] for c in heat_matrix.columns]

    fig_heat = go.Figure(go.Heatmap(
        z=heat_matrix.values,
        x=heat_matrix.columns.tolist(),
        y=heat_matrix.index.tolist(),
        colorscale=[
            [0.00, "#0d1b2a"],
            [0.01, "#1a2b3c"],
            [0.10, "#ffa50044"],
            [0.30, "#ffa500"],
            [1.00, "#ff4b4b"],
        ],
        zmin=0, zmax=100,
        text=heat_matrix.values,
        texttemplate="%{text:.0f}",
        textfont=dict(size=8, color="#ffffff"),
        hovertemplate="Date: %{x}<br>Column: %{y}<br>Null rate: %{z:.1f}%<extra></extra>",
        showscale=True,
        colorbar=dict(
            title=dict(text="Null %", font=dict(color="#8fa3b1", size=11)),
            ticksuffix="%",
            tickfont=dict(color="#8fa3b1"),
            thickness=12,
        ),
    ))
    fig_heat.update_layout(
        **CHART_LAYOUT,
        title="Null % per Column per Source File  (orange/red = problem zone)",
        height=360,
        xaxis=dict(title="File Date (MM-DD)", tickangle=-45,
                   tickfont=dict(size=9), **GRID),
        yaxis=dict(title="Column", autorange="reversed", tickfont=dict(size=11)),
        margin=dict(t=55, b=60, l=110, r=80),
    )
    st.plotly_chart(fig_heat, use_container_width=True)
    st.caption("Any cell above 5% (amber) warrants investigation. March 26 shows the null spike in unit_price and product_name.")

    # ── Row Counts per File ────────────────────────────────────────────────────
    st.markdown('<div class="section-label">Row Counts per Source File</div>', unsafe_allow_html=True)

    rc = query(con, """
        SELECT CAST(_file_date AS VARCHAR) AS file_date, COUNT(*) AS row_count
        FROM raw_orders
        GROUP BY _file_date
        ORDER BY _file_date
    """)
    rc["in_range"] = rc["row_count"].between(5000, 10000)
    rc["bar_color"] = rc["in_range"].map({True: "#34d399", False: "#ff4b4b"})

    fig_rc = go.Figure(go.Bar(
        x=rc["file_date"].str[5:],  # MM-DD only
        y=rc["row_count"],
        marker=dict(color=rc["bar_color"], opacity=0.85),
        hovertemplate="<b>%{x}</b><br>Rows: %{y:,}<extra></extra>",
    ))
    fig_rc.add_hline(y=5000,  line_dash="dot", line_color="#ff4b4b",
                     annotation_text="Min 5k",  annotation_font_color="#ff4b4b", annotation_font_size=10)
    fig_rc.add_hline(y=10000, line_dash="dot", line_color="#ff4b4b",
                     annotation_text="Max 10k", annotation_font_color="#ff4b4b", annotation_font_size=10)
    fig_rc.update_layout(
        **CHART_LAYOUT,
        title="Rows Loaded per Source File (green = within 5k–10k range)",
        height=300,
        showlegend=False,
        xaxis=dict(title="File Date (MM-DD)", tickangle=-45, tickfont=dict(size=9), **GRID),
        yaxis=dict(title="Row Count", tickformat=",", **GRID),
        margin=dict(t=50, b=60, l=60, r=10),
    )
    st.plotly_chart(fig_rc, use_container_width=True)

    # ── Duplicate Order IDs ────────────────────────────────────────────────────
    st.markdown('<div class="section-label">Duplicate Order IDs — Pre-Deduplication Snapshot</div>',
                unsafe_allow_html=True)

    dups = query(con, """
        SELECT
            order_id,
            COUNT(*) AS occurrences,
            MIN(_source_file) AS first_file,
            MAX(_source_file) AS last_file
        FROM raw_orders
        WHERE order_id IS NOT NULL
        GROUP BY order_id
        HAVING COUNT(*) > 1
        ORDER BY occurrences DESC
        LIMIT 25
    """)

    if len(dups) == 0:
        st.success("No duplicate order_ids found in raw_orders.")
    else:
        total_excess = int(dups["occurrences"].sum() - len(dups))
        st.warning(
            f"{len(dups):,} duplicate order_ids detected ({total_excess:,} excess rows total). "
            "All resolved by the deduplication step in transform.py — fact_orders contains only unique order_ids.",
            icon="⚠️",
        )
        st.dataframe(dups, use_container_width=True, hide_index=True)

    # ── Quarantine Summary ─────────────────────────────────────────────────────
    st.markdown('<div class="section-label">Quarantine Summary — Rows Excluded from Revenue</div>',
                unsafe_allow_html=True)
    try:
        quar = query(con, """
            SELECT CAST(_file_date AS VARCHAR) AS file_date, COUNT(*) AS quarantined
            FROM quarantine_orders
            GROUP BY _file_date
            ORDER BY _file_date
        """)
        if len(quar) == 0:
            st.success("No quarantined rows — all loaded rows met quality thresholds.")
        else:
            total_q = int(quar["quarantined"].sum())
            st.warning(
                f"{total_q:,} rows quarantined (NULL in a critical revenue field). "
                "These rows exist in quarantine_orders and are fully excluded from fact_orders and all revenue metrics.",
                icon="⚠️",
            )
            fig_quar = go.Figure(go.Bar(
                x=quar["file_date"].str[5:],
                y=quar["quarantined"],
                marker=dict(color="#ff4b4b", opacity=0.8),
                hovertemplate="<b>%{x}</b><br>Quarantined: %{y:,}<extra></extra>",
            ))
            fig_quar.update_layout(
                **CHART_LAYOUT,
                title="Quarantined Rows per Source File",
                height=260,
                showlegend=False,
                xaxis=dict(title="File Date (MM-DD)", tickangle=-45,
                           tickfont=dict(size=9), **GRID),
                yaxis=dict(title="Rows Quarantined", tickformat=",", **GRID),
                margin=dict(t=50, b=60, l=60, r=10),
            )
            st.plotly_chart(fig_quar, use_container_width=True)
    except Exception:
        st.info("quarantine_orders table not found. Re-run the pipeline to generate it.")
